def solve(inputs: dict) -> float:
    # Expected inputs: {'n': int, 'k': int} or equivalent keys
    n = inputs.get('n', inputs.get('N'))
    k = inputs.get('k', inputs.get('K'))
    if n is None:
        # try common alternative wording
        n = inputs.get('people', inputs.get('count'))
    if k is None:
        k = inputs.get('step', inputs.get('every'))
    n = int(n)
    k = int(k)
    s = 0
    for i in range(1, n + 1):
        s = (s + k) % i
    return float(s + 1)

