def solve(inputs: dict) -> float:
    terms = inputs.get('terms', inputs.get('a'))
    if terms is None:
        terms = inputs.get('cf', inputs.get('continued_fraction'))
    p_prev2 = 1
    p_prev1 = terms[0]
    if len(terms) == 1:
        return float(p_prev1)
    for a in terms[1:]:
        p = a * p_prev1 + p_prev2
        p_prev2, p_prev1 = p_prev1, p
    return float(p_prev1)

